INSERT INTO seo_brand_voices (site_id, voice_name, personality_traits, primary_tone, vocabulary_rules, microcopy_rules, sample_headlines, sample_meta_descriptions, updated_at)
VALUES ('maui', 'Wailea Oceanfront Elegance & Upcountry Sourcing', '{"Refined","Oceanfront","Romantic","Artisanal","Dusk-Mauve Warmth"}', 'Sensory, luxurious, warm, and deeply respectful of Maui agriculture. Tailored for oceanfront villa dinner parties in Wailea/Mākena and luxury retreats in Kapalua.', '{"forbidden_terms":["Book now","Budget catering Maui"],"required_terms":["Wailea","Kapalua","Mākena","Kula Country Farms","Maui Cattle Company","Maʻalaea day-boat fleet"]}'::jsonb, '{"cta_primary":"Get a Maui Written Quote","cta_secondary":"View Maui Rate Card","pricing_disclaimer":"Wailea villa dinners from $150/guest. Stay Chef from $1,050/day."}'::jsonb, '{"Private Chef Maui — Wailea Villa Dinners, Weddings & Stay Chef","The oceanfront dinner party in Wailea. Local day-boat fish, sunset lanai service."}', '{"Private chef and catering across Maui. Wailea villa dinners from $150/guest, Stay Chef from $1,050/day. Written quotes, zero hidden fees."}', NOW());
INSERT INTO seo_brand_voices (site_id, voice_name, personality_traits, primary_tone, vocabulary_rules, microcopy_rules, sample_headlines, sample_meta_descriptions, updated_at)
VALUES ('kauai', 'Garden Isle Tranquility & Two-Shore Estate Logistics', '{"Serene","Unrushed","Intimate","Deeply Rooted","Restorative"}', 'Quiet luxury, unhurried hospitality, and deep respect for island geography. Addresses Hanalei to Poʻipū logistics with unflinching mastery.', '{"forbidden_terms":["Book now","Quick catering"],"required_terms":["Princeville","Hanalei","Poʻipū","Kauaʻi Shrimp","Makaweli Meat Company","Two shores"]}'::jsonb, '{"cta_primary":"Get a Kauaʻi Written Quote","cta_secondary":"View Kauaʻi Pricing","pricing_disclaimer":"Both shores served. Written quotes, groceries at cost."}'::jsonb, '{"Private Chef Kauaʻi — Princeville, Hanalei & Poʻipū Estates","A chef for the house on Kauaʻi. From North Shore bluffs to sunny Poʻipū."}', '{"Private chef and estate dining on Kauaʻi. Signature dinners from $150/guest. Princeville, Hanalei, Poʻipū. Written quotes."}', NOW());
INSERT INTO seo_brand_voices (site_id, voice_name, personality_traits, primary_tone, vocabulary_rules, microcopy_rules, sample_headlines, sample_meta_descriptions, updated_at)
VALUES ('bigisland', 'Kona–Kohala Volcanic Luxury & Gated Community Residency', '{"Expansive","Exclusive","Resolute","Ranch-to-Table","Estate-Focused"}', 'Prestigious, private, and discreet. Speaks to homeowners and villa guests within Kūkiʻo, Hualālai, Kohanaiki, and Mauna Kea.', '{"forbidden_terms":["Book now","Cheap private chef Kona"],"required_terms":["Kūkiʻo","Hualālai","Kohanaiki","Mauna Lani","Parker Ranch","Honokōhau day-boat","Gated community security protocol"]}'::jsonb, '{"cta_primary":"Get a Big Island Written Quote","cta_secondary":"View Big Island Rate Card","pricing_disclaimer":"Gated community gate passes coordinated. Written quotes, confirmed totals."}'::jsonb, '{"Private Chef Big Island — Kona–Kohala & Gated Estates","Cooking in Kūkiʻo, Hualālai, and Kohanaiki. Private villa chef service from $150/guest."}', '{"Private chef service on Hawaiʻi Island, Kona–Kohala first. Villa dinners from $150/guest, Stay Chef from $950/day. Gated community access."}', NOW());

