-- 6. INITIAL SPLIT-TEST EXPERIMENTS ("enable automatic split testing, title & meta text")
DO $$
DECLARE
  v_page_id UUID;
  v_test_id UUID;
BEGIN
  SELECT page_id INTO v_page_id FROM seo_pages WHERE url = 'https://mychef-hawaii.com/';
  IF v_page_id IS NOT NULL THEN
    INSERT INTO seo_split_tests (page_id, site_id, test_type, hypothesis, target_metric, status, started_at, test_duration_days)
    VALUES (v_page_id, 'hub', 'TITLE_META_SERP', 'Testing explicit statewide multi-island positioning against luxury private villa positioning to maximize high-intent corporate/wedding CTR.', 'CTR', 'ACTIVE', NOW(), 30)
